<?php

declare(strict_types=1);

namespace Unitary\Preferences;

use Brick\Math\BigRational;
use Brick\Math\RoundingMode;
use InvalidArgumentException;
use Unitary\Breakdown;
use Unitary\Dimension;
use Unitary\Quantity;
use Unitary\Substances\SubstanceConverter;
use Unitary\Substances\Substances;
use Unitary\Unit;
use Unitary\Units\Temperature;
use Unitary\Units\TemperatureDifference;
use Unitary\UnitRegistry;

/**
 * Picks the unit a region uses for a kind of value, from CLDR's unit
 * preferences (resources/cldr, generated by bin/update-cldr-data.php):
 *
 *     80 km, en-GB, road           →  49.71 mi
 *     80 km, sv-SE, road           →  8 mil
 *     180 cm, en-US, person-height →  5 ft 10.87 in
 *     80 kg, en-GB, person         →  12 st 8.37 lb
 *
 * Within a usage, each region has a list of units from largest to smallest.
 * The first whose value reaches its threshold wins, and some round to an
 * increment (road distances under a kilometre go to the nearest 10 or 50 m).
 */
final class UnitPreferences
{
    /** CLDR categories searched for each dimension, in order. */
    private const CATEGORIES = [
        'length' => ['length'],
        'mass' => ['mass'],
        'time' => ['duration', 'year-duration'],
        'temperature' => ['temperature'],
        'temperature_difference' => ['temperature'],
        'area' => ['area'],
        'volume' => ['volume'],
        'speed' => ['speed'],
        'pressure' => ['pressure'],
        'energy' => ['energy'],
        'power' => ['power'],
        'force' => ['force'],
        'fuel_economy' => ['consumption'],
        'density' => ['mass-density', 'concentration'],
        'molar_concentration' => ['concentration'],
    ];

    /** CLDR abbreviates some usage names; accept the full words too. */
    private const USAGE_ALIASES = ['visibility' => 'visiblty', 'barometric' => 'baromtrc'];

    /** @var array<string, array<string, list<array{regions: list<string>, units: list<string>, geq: string, increment: ?string}>>>|null */
    private static ?array $data = null;

    /**
     * Expresses a quantity the way a region would. $locale is a locale ("en-GB",
     * "sv_SE") or a region code ("GB"); a locale without a region, like "en",
     * gets the worldwide default. Unknown usages fall back to the default for
     * the dimension, and dimensions CLDR has no preferences for come back unchanged.
     *
     * @param  Quantity<Unit>  $quantity
     * @return Quantity<Unit>|Breakdown
     */
    public static function apply(Quantity $quantity, string $locale, string $usage = 'default'): Quantity|Breakdown
    {
        $rows = self::rows($quantity->dimension(), self::regionOf($locale), $usage);

        if ($rows === []) {
            return $quantity;
        }

        $last = count($rows) - 1;

        foreach ($rows as $index => $row) {
            $first = self::convert($quantity, $row['units'][0]);

            if ($index === $last || $first->value()->abs()->isGreaterThanOrEqualTo(BigRational::of($row['geq']))) {
                return self::express($quantity, $first, $row);
            }
        }

        return $quantity;
    }

    /**
     * The usages CLDR has preferences for in a dimension: "road", "person-height"...
     *
     * @return list<string>
     */
    public static function usages(Dimension $dimension): array
    {
        $usages = [];

        foreach (self::CATEGORIES[$dimension->value] ?? [] as $category) {
            $usages = [...$usages, ...array_keys(self::data()[$category] ?? [])];
        }

        return array_values(array_unique($usages));
    }

    /**
     * The region in a locale or region code: "en-GB" → "GB", "zh_Hant_TW" → "TW",
     * "es-419" → "419", "se" → "001" (a language alone has no region).
     */
    public static function regionOf(string $locale): string
    {
        $parts = preg_split('/[-_]/', trim($locale)) ?: [];

        // A bare two-letter code in upper case is a region ("GB"); in lower case it's a language ("en").
        if (count($parts) === 1) {
            return preg_match('/^(?:[A-Z]{2}|\d{3})$/', $parts[0]) === 1 ? $parts[0] : '001';
        }

        foreach (array_slice($parts, 1) as $part) {
            if (preg_match('/^(?:[A-Za-z]{2}|\d{3})$/', $part) === 1) {
                return strtoupper($part);
            }
        }

        return '001';
    }

    /**
     * @return list<array{regions: list<string>, units: list<string>, geq: string, increment: ?string}>
     */
    private static function rows(Dimension $dimension, string $region, string $usage): array
    {
        $categories = self::CATEGORIES[$dimension->value] ?? [];
        $data = self::data();
        $rows = null;
        $usage = self::USAGE_ALIASES[$usage] ?? $usage;

        // "person-height" falls back to "person", then to "default".
        foreach ([...self::fallbacks($usage), 'default'] as $candidate) {
            foreach ($categories as $category) {
                if (isset($data[$category][$candidate])) {
                    $rows = $data[$category][$candidate];

                    break 2;
                }
            }
        }

        if ($rows === null) {
            return [];
        }

        $forRegion = array_values(array_filter($rows, fn (array $row) => in_array($region, $row['regions'], true)));

        return $forRegion !== [] ? $forRegion : array_values(array_filter($rows, fn (array $row) => in_array('001', $row['regions'], true)));
    }

    /**
     * @return list<string>
     */
    private static function fallbacks(string $usage): array
    {
        $usages = [];

        for ($parts = explode('-', $usage); $parts !== []; array_pop($parts)) {
            $usages[] = implode('-', $parts);
        }

        return $usages;
    }

    /**
     * @param  Quantity<Unit>  $quantity
     * @return Quantity<Unit>
     */
    private static function convert(Quantity $quantity, string $symbol): Quantity
    {
        $unit = UnitRegistry::default()->resolve($symbol);

        // A preference for °F applied to a change in temperature means Fahrenheit degrees.
        if ($quantity->unit() instanceof TemperatureDifference && $unit instanceof Temperature) {
            $unit = $unit->difference();
        }

        // Blood glucose: mmol/L and mg/dL only convert through glucose's molar mass.
        if (in_array($quantity->dimension(), [Dimension::Density, Dimension::MolarConcentration], true) && $unit->dimension() !== $quantity->dimension()) {
            $glucose = Substances::find('glucose') ?? throw new InvalidArgumentException('The glucose substance is missing');

            return SubstanceConverter::convert($quantity, $glucose, $unit);
        }

        return $quantity->to($unit);
    }

    /**
     * @param  Quantity<Unit>  $quantity
     * @param  Quantity<Unit>  $first  the quantity in the row's first unit
     * @param  array{regions: list<string>, units: list<string>, geq: string, increment: ?string}  $row
     * @return Quantity<Unit>|Breakdown
     */
    private static function express(Quantity $quantity, Quantity $first, array $row): Quantity|Breakdown
    {
        if (count($row['units']) > 1) {
            return Breakdown::of($first, ...$row['units']);
        }

        if ($row['increment'] === null) {
            return $first;
        }

        $increment = BigRational::of($row['increment']);
        $steps = $first->value()->dividedBy($increment)->toScale(0, RoundingMode::HalfUp)->toBigRational();

        return new Quantity($steps->multipliedBy($increment), $first->unit(), uncertainty: $first->uncertainty());
    }

    /**
     * @return array<string, array<string, list<array{regions: list<string>, units: list<string>, geq: string, increment: ?string}>>>
     */
    private static function data(): array
    {
        if (self::$data === null) {
            /** @var array{preferences: array<string, array<string, list<array{regions: list<string>, units: list<string>, geq: string, increment: ?string}>>>} $file */
            $file = require dirname(__DIR__, 2).'/resources/cldr/unit-preferences.php';
            self::$data = $file['preferences'];
        }

        return self::$data;
    }
}
